import re
def validate(password: str) -> dict:
    errors = []
    if len(password) < 8:
        errors.append('Minimo 8 caracteres')
    if not re.search(r'[A-Z]', password):
        errors.append('Debe contener mayuscula')
    if not re.search(r'[a-z]', password):
        errors.append('Debe contener minuscula')
    if not re.search(r'\d', password):
        errors.append('Debe contener digito')
    if not re.search(r'[^A-Za-z0-9]', password):
        errors.append('Debe contener caracter especial')
    return {'valid': len(errors) == 0, 'errors': errors}

